def nearest_perfect_square(n):
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid * mid <= n:
            lo = mid
        else:
            hi = mid - 1
    lower = lo * lo
    upper = (lo + 1) * (lo + 1)
    return upper if upper - n < n - lower else lower

