def invert_one_to_many(d):
    from itertools import groupby
    pairs = sorted(d.items(), key=lambda kv: (kv[1], kv[0]))
    result = {}
    for value, group in groupby(pairs, key=lambda kv: kv[1]):
        result[value] = [k for k, _ in group]
    return result

