def truncate_middle(s, maxlen):
    if len(s) <= maxlen:
        return s
    if maxlen <= 3:
        return s[:maxlen]
    keep = maxlen - 3
    right_len = keep // 2
    left_len = keep - right_len
    return s[:left_len] + '...' + (s[-right_len:] if right_len else '')

