def top_k_elements(lst, k):
    if k <= 0:
        return []
    remaining = list(lst)
    result = []
    for _ in range(min(k, len(remaining))):
        highest = max(remaining)
        result.append(highest)
        remaining.remove(highest)
    return result

def flatten_dict_tuple_keys(d):
    result = {}
    stack = [((), d)]
    while stack:
        path, node = stack.pop()
        for k, v in node.items():
            new_path = path + (k,)
            if isinstance(v, dict) and v:
                stack.append((new_path, v))
            else:
                result[new_path] = v
    return result

