def count_palindromic_substrings(s):
    n = len(s)
    count = 0
    for length in range(1, n + 1):
        for start in range(n - length + 1):
            end = start + length - 1
            l, r = start, end
            is_pal = True
            while l < r:
                if s[l] != s[r]:
                    is_pal = False
                    break
                l += 1
                r -= 1
            if is_pal:
                count += 1
    return count

import itertools

def merge_alternating_reverse(a, b):
    sentinel = object()
    merged = []
    for x, y in itertools.zip_longest(a, reversed(b), fillvalue=sentinel):
        if x is not sentinel:
            merged.append(x)
        if y is not sentinel:
            merged.append(y)
    return merged
